import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Handlers container
  root.userData.handlers = {};

  // Store primitives for cleanup
  const primitiveInstances = [];

  // -----------------------------------------------------------------
  // Load GLB mesh (synchronous return, async loading inside)
  // -----------------------------------------------------------------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const mesh = gltf.scene;
      root.add(mesh);
    });
  }

  // -----------------------------------------------------------------
  // Apply cinematic primitives defined in config
  // -----------------------------------------------------------------
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach((p) => {
    const instance = ctx.primitives[p.name](root, p.params);
    primitiveInstances.push(instance);
  });

  // -----------------------------------------------------------------
  // Interaction: Hover – rise‑in preset (0.15 scene units)
  // -----------------------------------------------------------------
  let hoverTimeline = null;
  root.userData.handlers.hover = () => {
    // if any previous hover animation is running, kill it first
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: `+=0.15`,
      duration: 0.7,
      ease: 'power3.out',
    });
  };
  // Optional leave handler (revert the rise‑in)
  root.userData.handlers.hoverLeave = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: `-=${0.15}`,
      duration: 0.3,
      ease: 'power3.in',
    });
  };

  // -----------------------------------------------------------------
  // Interaction: Click – emit navigation event
  // -----------------------------------------------------------------
  root.userData.handlers.click = () => {
    ctx.emit('hub-features.select');
  };

  // -----------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // Kill hover timeline if present
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup all primitives (timeline + resources)
    primitiveInstances.forEach((inst) => {
      if (inst) {
        if (inst.timeline && typeof inst.timeline.kill === 'function') {
          inst.timeline.kill();
        }
        if (typeof inst.cleanup === 'function') {
          inst.cleanup();
        }
      }
    });

    // Dispose geometries and materials from the loaded GLB
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
